//! AES-256-GCM encryption
//!
//! # Backend (item 6.4)
//!
//! The AEAD is libcrux-aesgcm (pure Rust) instead of RustCrypto's `aes-gcm`. This
//! is an *implementation* swap behind byte-identical `encrypt`/`decrypt` entry
//! points: for the same key/nonce/AAD the ciphertext and tag are the same bytes, so
//! the wire format, the cipher suite, and every published sentence stay as they
//! were. `tests/aes_gcm_differential.rs` pins that against the implementation this
//! replaced (2000 cases, byte-for-byte, both directions) plus one fixed vector
//! generated by the pre-swap backend.
//!
//! On aarch64 the fast path is selected by the `+aes` **target feature**, not by
//! libcrux's own `simd128` feature (see `.cargo/config.toml` and the 6.4
//! measurement). Without it libcrux silently assembles its bitsliced fallback —
//! 111 MB/s against 973 MB/s measured on this box, a ~9x silent cliff that
//! `scripts/gates/run-bench-gates.sh` exists to catch. That flag is load-bearing.

use libcrux_aesgcm::aes_gcm_256::{Key as LKey, Nonce as LNonce, Tag as LTag};
use libcrux_aesgcm::{AeadConsts as _, AesGcm256};
use zeroize::Zeroize;

use crate::error::{CryptoError, Result};

/// Encrypt data using AES-256-GCM
///
/// # Arguments
///
/// * `key` - 32-byte encryption key
/// * `nonce` - 12-byte nonce (must be unique per message)
/// * `plaintext` - Data to encrypt
/// * `aad` - Additional authenticated data (can be empty)
///
/// # Returns
///
/// Ciphertext with authentication tag appended
pub fn encrypt(key: &[u8; 32], nonce: &[u8; 12], plaintext: &[u8], aad: &[u8]) -> Result<Vec<u8>> {
    let key: LKey = (*key).into();
    let nonce: LNonce = (*nonce).into();

    let mut ciphertext = vec![0u8; plaintext.len()];
    let mut tag: LTag = [0u8; AesGcm256::TAG_LEN].into();
    let mut tag_bytes = [0u8; AesGcm256::TAG_LEN];

    key.encrypt(&mut ciphertext, &mut tag, &nonce, aad, plaintext)
        .map_err(|_| CryptoError::Encryption("AES-GCM encryption failed".to_string()))?;
    tag_bytes.copy_from_slice(tag.as_ref());

    // Wire format, unchanged: ciphertext || tag (exactly what `aes-gcm` emitted).
    ciphertext.extend_from_slice(&tag_bytes);
    Ok(ciphertext)
}

/// Decrypt data using AES-256-GCM
///
/// # Arguments
///
/// * `key` - 32-byte encryption key
/// * `nonce` - 12-byte nonce (must match encryption nonce)
/// * `ciphertext` - Data to decrypt (includes authentication tag)
/// * `aad` - Additional authenticated data (must match encryption AAD)
///
/// # Returns
///
/// Decrypted plaintext if authentication succeeds
pub fn decrypt(key: &[u8; 32], nonce: &[u8; 12], ciphertext: &[u8], aad: &[u8]) -> Result<Vec<u8>> {
    if ciphertext.len() < AesGcm256::TAG_LEN {
        return Err(CryptoError::Decryption(
            "AES-GCM decryption failed: input is shorter than the authentication tag".to_string(),
        ));
    }
    let key: LKey = (*key).into();
    let nonce: LNonce = (*nonce).into();

    // Wire format, unchanged: the trailing 16 bytes are the tag.
    let (body, tag_bytes) = ciphertext.split_at(ciphertext.len() - AesGcm256::TAG_LEN);
    let mut tag_arr = [0u8; AesGcm256::TAG_LEN];
    tag_arr.copy_from_slice(tag_bytes);
    let tag: LTag = tag_arr.into();

    let mut plaintext = vec![0u8; body.len()];
    // libcrux's decrypt argument order differs from its encrypt: (out, nonce, aad,
    // ciphertext, tag) — see libcrux-traits' typed-refs `Aead`.
    key.decrypt(&mut plaintext, &nonce, aad, body, &tag)
        .map_err(|_| {
            // Never hand back unauthenticated bytes.
            plaintext.zeroize();
            CryptoError::Decryption("AES-GCM decryption failed".to_string())
        })?;
    Ok(plaintext)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_aes_gcm_roundtrip() {
        let key = [0u8; 32];
        let nonce = [1u8; 12];
        let plaintext = b"hello world";
        let aad = b"metadata";

        let ciphertext = encrypt(&key, &nonce, plaintext, aad).unwrap();
        let decrypted = decrypt(&key, &nonce, &ciphertext, aad).unwrap();

        assert_eq!(plaintext, decrypted.as_slice());
    }

    #[test]
    fn test_aes_gcm_wrong_key() {
        let key1 = [0u8; 32];
        let key2 = [1u8; 32];
        let nonce = [1u8; 12];
        let plaintext = b"secret";

        let ciphertext = encrypt(&key1, &nonce, plaintext, &[]).unwrap();
        let result = decrypt(&key2, &nonce, &ciphertext, &[]);

        assert!(result.is_err());
    }

    #[test]
    fn test_aes_gcm_wrong_aad() {
        let key = [0u8; 32];
        let nonce = [1u8; 12];
        let plaintext = b"secret";
        let aad1 = b"metadata1";
        let aad2 = b"metadata2";

        let ciphertext = encrypt(&key, &nonce, plaintext, aad1).unwrap();
        let result = decrypt(&key, &nonce, &ciphertext, aad2);

        assert!(result.is_err());
    }

    /// One fixed vector produced by the backend that shipped before item 6.4
    /// (`aes-gcm` 0.10.3, the same implementation the differential test uses as its
    /// oracle), pinned so this swap cannot drift from the bytes peers already hold.
    #[test]
    fn test_shipped_vector_survives_the_backend_swap() {
        let key = [0x2bu8; 32];
        let nonce = [0x11u8; 12];
        let aad = b"tallow-transfer-scope-v1";
        let pt = b"TAllow wire-compat vector (pre-swap backend: aes-gcm 0.10.3)";
        let ct_tag = hex::decode(
            "ec070139e090c2fdd89a72d4adbf3835ca17d3409ed11fbba07af2edd9240fec9624ab8976755f036ce1aed11fb5e4c55d088a961c67086a49131afdbcf4f0459cc5357be08c61ddd09261c1",
        )
        .unwrap();

        assert_eq!(encrypt(&key, &nonce, pt, aad).unwrap(), ct_tag);
        assert_eq!(decrypt(&key, &nonce, &ct_tag, aad).unwrap(), pt);
    }
}
